const body = $input.first().json.body;
const dest = body.destination || '台灣';
const dailyAreas = (body.daily_area || []).filter(a => a && a !== '不限區域');
const areasStr = dailyAreas.length > 0 ? dailyAreas.join(' ') : dest;
const preference = body.preference || '一般旅遊';
const spotQuery = `${dest} ${areasStr} 旅遊景點推薦 必去景點 ${preference} 評價`;
const foodQuery = `${dest} ${areasStr} 必吃美食推薦 在地美食 餐廳 小吃 2024`;
const activityQuery = `${dest} ${areasStr} 一日遊 體驗活動 旅遊行程 KKday Klook 推薦`;
return [{ json: { body, spot_query: spotQuery, food_query: foodQuery, activity_query: activityQuery } }];

const spotResults = $input.first().json;
const prepareData = $('Prepare').first().json;
const spotSnippets = (spotResults.organic || []).slice(0, 6).map((r, i) => `[${i+1}] ${r.title}\n${r.snippet || ''}`).join('\n');
return [{ json: { body: prepareData.body, food_query: prepareData.food_query, activity_query: prepareData.activity_query, spot_summary: spotSnippets } }];

const captured = $('Capture Spots').first().json;
const foodResults = $input.first().json;
const foodSnippets = (foodResults.organic || []).slice(0, 8).map((r, i) => `[${i+1}] ${r.title}: ${r.snippet || ''}`).join('\n').substring(0, 2000);
return [{ json: { body: captured.body, activity_query: captured.activity_query, spot_summary: captured.spot_summary, food_summary: foodSnippets } }];

const capturedFood = $('Capture Food').first().json;
const body = capturedFood.body;
const actResults = $input.first().json;

const actSnippets = (actResults.organic || []).slice(0, 5).map((r, i) => `[${i+1}] ${r.title}: ${r.snippet || ''} ${r.link || ''}`).join('\n').substring(0, 1500);

const dailyAreaArr = body.daily_area || [];
const dailyDirArr = body.daily_direction || [];
const dailyAreaStr = JSON.stringify(dailyAreaArr);
const dailyDirStr = dailyDirArr.map((d, i) => d ? `第 ${i+1} 天：${d}` : '').filter(Boolean).join('\n') || '無';

const areaRules = dailyAreaArr.map((area, i) =>
  area && area !== '不限區域'
    ? `第 ${i+1} 天：所有景點【必須】在「${area}」範圍內，嚴禁安排其他區域景點`
    : `第 ${i+1} 天：自由安排`
).join('\n');

const departHour = parseInt((body.depart_time || '09:00').split(':')[0]);
const returnHour = parseInt((body.return_time || '15:00').split(':')[0]);

let timeRules = '';
if (departHour >= 11) timeRules += '- 第一天從下午開始排，不排早上景點\n';
else if (departHour >= 10) timeRules += '- 第一天早上只排1個景點\n';
if (returnHour <= 11) timeRules += '- 最後一天不排任何景點\n';
else if (returnHour <= 14) timeRules += '- 最後一天只排早上，不排下午\n';
timeRules += `- 最後一天 ${body.return_time || '15:00'} 前2小時停止安排景點`;

const specialNote = body.special_request ? `特別需求（優先排入）：${body.special_request}` : '';

const uniqueAreas = [...new Set(dailyAreaArr.filter(a => a && a !== '不限區域'))];
const geoRule = uniqueAreas.length > 1
  ? `多天行程每天必須在不同地理區域（${uniqueAreas.join('、')}），禁止多天都集中在同一條街或同一個公園`
  : '多天行程要分散在不同區域，避免連續幾天都在同一個公園或同一條街';

const systemPrompt = `你是台灣旅遊規劃專家。根據以下最新網路搜尋結果和使用者條件，規劃詳細的旅遊行程。請優先使用搜尋結果中出現的景點和餐廳。

=== 最新景點搜尋結果 ===
${capturedFood.spot_summary}

=== 最新美食搜尋結果 ===
${capturedFood.food_summary}

=== KKday/Klook 體驗活動搜尋結果 ===
${actSnippets}

==== 每天區域限制（最高優先級，違反視為錯誤） ====
${areaRules}
例如：七星潭屬於吉安鄉，若第1天指定花蓮市區，七星潭絕對不可出現在第1天。

==== 【硬性規則，違反以下任何一條視為輸出錯誤】 ====
★ 規則1 - 景點唯一性：整個行程每個景點/地點名稱只能出現「恰好一次」。
  不論跨天、跨時段，同一個景點名稱絕對不能重複出現。
★ 規則2 - 夜市強制晚上：任何名稱含「夜市」的地點，只能放在 evening 時段。
  出現在 morning 或 afternoon 等於嚴重錯誤，違反此規則的行程必須重新規劃。
★ 規則3 - 夜市限額：整個行程夜市最多出現 2 個（且必須是不同的夜市名稱）。
  每天的 evening 最多安排 1 個夜市。
★ 規則4 - 子景點合併：同一個景區/公園/山區內的子景點，同一天只選最具代表性的 1 個。
  反例（錯誤）：同一天排「射日塔」＋「忠烈祠」＋「嘉義公園」＋「福康安紀功碑」→ 這四個都在嘉義公園內，只能選其一。
  正例（正確）：同一天選「射日塔（嘉義公園）」，其他子景點忽略。
★ 規則5 - 地理多樣性：多天行程每天的重心區域要不同，${geoRule}。
★ 規則6 - 景點多樣性：每天要包含不同類型（文化歷史 + 自然風景 + 美食/市集），不要整天只有歷史古蹟或整天只有景點類。

==== 時段邏輯（嚴格遵守） ====
morning（早上）只能排：博物館、自然景觀、老街、寺廟、咖啡廳、文化景點、早市
  ★ 絕對禁止：夜市、夜景、酒吧、任何名稱含「夜」字的地點
afternoon（下午）只能排：景點參觀、下午茶、海灘、文創園區、老街、博物館
  ★ 絕對禁止：夜市、夜景
evening（晚上）只能排：夜市、夜景、燈會、晚餐名店、夜間活動
  ★ 禁止：博物館（通常晚上關閉）、一般白天自然景點
${timeRules}

${specialNote}

其他規則：
1. 只回傳純 JSON，不可加任何說明文字或 markdown
2. 每天：早上2個、下午2個、晚上1個（時間規則例外）
3. type 只能填「景點」或「美食"
4. note 是一句30字以內的中文介紹（根據搜尋結果整理）
5. 每個景點必須提供 nearby_food（3-5 個真實店家）
6. nearby_food 必須有【真實店名】：
   - 不接受「路邊攤」「當地小吃」等籠統描述
   - 必須是真實存在的店名，例如：「阿桐阿寶四神湯」「員林張家肉圓」
   - address 必須是真實地址，不可只寫「夜市內」或「當地」
7. 夜市類景點的 nearby_food 改為夜市內 3-5 個【具名攤位】
8. 座標 lat/lng 必須準確（緯度 21-26.5，經度 118-123）
9. maps_url 格式：https://maps.google.com/?q=景點名稱+城市
10. 若有相關 KKday/Klook 體驗，加入 activities 陣列（最多2個）；沒有則填空陣列

輸出格式（必須包含所有 ${body.days} 天，不可省略）：
{"title":"城市名","days":天數,"itinerary":[{"day":1,"area":"區域名","morning":[{"type":"景點","name":"名稱","note":"介紹","address":"地址","maps_url":"url","lat":00.0000,"lng":000.0000,"nearby_food":[{"name":"店名","type":"類型","note":"介紹","address":"地址"}],"activities":[],"photo_keyword":"English keyword"}],"afternoon":[...],"evening":[...]}]}`;

const userMessage = `請為以下條件規劃行程：\n目的地：${body.destination}，天數：${body.days}天\n大人：${body.adults}人，小孩：${body.kids || 0}人\n旅遊傾向：${body.preference}，住宿：${body.accommodation}\n每天區域：${dailyAreaStr}\n每天方向：${dailyDirStr}\n\n【輸出前自我檢查】\n(1) 有沒有同一個景點名稱出現超過1次？有的話必須替換其中一個。\n(2) 有沒有夜市被排在 morning 或 afternoon？有的話必須移到 evening 或改成別的景點。\n(3) 同一個公園/景區的子景點，同一天有沒有出現超過1個？有的話刪掉多餘的。\n(4) 是否輸出了完整的 ${body.days} 天？不可只輸出1天。`;

const maxTokens = Math.min(body.days * 2000 + 2000, 12000);

return [{ json: { model: 'gpt-4o-mini', response_format: { type: 'json_object' }, temperature: 0.7, max_tokens: maxTokens, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userMessage }] } }];

const raw = $input.first().json.choices[0].message.content;
const result = JSON.parse(raw);
return [{ json: result }];

// Post-process: 程式層去重 + 時段修正（最後防線）
const data = $input.first().json;
const itinerary = data.itinerary || [];

const globalNames = new Set();

itinerary.forEach(day => {
  // 先把所有夜市從 morning/afternoon 收集起來，準備搬到 evening
  const displacedNightMarkets = [];

  ['morning', 'afternoon'].forEach(slot => {
    if (!day[slot]) return;
    const kept = [];
    day[slot].forEach(spot => {
      if (!spot || !spot.name) return;
      const isNightMarket = spot.name.includes('夜市');
      if (isNightMarket) {
        // 收到暫存區，稍後嘗試放 evening
        displacedNightMarkets.push(spot);
        return;
      }
      if (globalNames.has(spot.name)) return; // 去重
      globalNames.add(spot.name);
      kept.push(spot);
    });
    day[slot] = kept;
  });

  // Evening：去重 + 加入被搬移的夜市（若 evening 還沒有夜市）
  if (!day.evening) day.evening = [];
  const keptEvening = [];
  let eveningNightMarketCount = 0;
  day.evening.forEach(spot => {
    if (!spot || !spot.name) return;
    if (globalNames.has(spot.name)) return;
    if (spot.name.includes('夜市')) eveningNightMarketCount++;
    globalNames.add(spot.name);
    keptEvening.push(spot);
  });
  // 若 evening 還沒有夜市，把搬移過來的第一個夜市加入
  if (eveningNightMarketCount === 0 && displacedNightMarkets.length > 0) {
    const nm = displacedNightMarkets[0];
    if (!globalNames.has(nm.name)) {
      globalNames.add(nm.name);
      keptEvening.push(nm);
    }
  }
  day.evening = keptEvening;
});

return [{ json: data }];
